  function ottoviasTollActionLabel(toll){if(!toll)return'Ação';if(Date.now()<Number(toll.openUntil||0))return'Passar';if(toll.paymentPending)return'Levantar';return'Pagar';}
  function ottoviasTollContextLabel(toll){if(!toll)return'Pedágio OTTOVIAS';if(Date.now()<Number(toll.openUntil||0))return`${toll.name} • cancela aberta`;if(toll.paymentPending)return`${toll.name} • levante a cancela`;return`${toll.name} • pedágio ${Number(toll.cost||5)} moedas`;}
  function handleOttoviasTollAction(id){const toll=ottoviasTollRecord(id);if(!toll)return false;if(!player.vehicle){toast('Entre com um veículo na faixa do pedágio.','warn',1800);return false;}if(Date.now()<Number(toll.openUntil||0)){toast('Cancela aberta. Siga pela faixa com atenção.','good',1300);return true;}if(toll.paymentPending)return raiseOttoviasTollGate(id);return payOttoviasToll(id);}
  function payOttoviasToll(id){const toll=ottoviasTollRecord(id),data=ensureOttoviasState();if(!toll)return false;if(!player.vehicle){toast('Entre com um veículo na faixa do pedágio.','warn',1800);return false;}if(toll.paymentPending){toast('Pagamento confirmado. Agora use LEVANTAR.','good',1500);return true;}const cost=Number(toll.cost||5);if(Number(state.profile.coins||0)<cost){toast(`Pedágio: ${cost} moedas. Saldo insuficiente.`,'warn',2200);return false;}const now=Date.now();addCoins(-cost);data.spent+=cost;data.lastTollId=id;data.lastTollAt=now;toll.paymentPending=true;toll.paidAt=now;saveState(true);updateContext?.(true);toast(`Pedágio pago • ${cost} moedas. Agora toque LEVANTAR.`,'good',2300);beep(920,70,'sine');return true;}
  function raiseOttoviasTollGate(id){const toll=ottoviasTollRecord(id);if(!toll||!player.vehicle)return false;if(!toll.paymentPending){toast('Primeiro pague o pedágio.','warn',1700);return false;}toll.openUntil=Date.now()+14000;updateContext?.(true);toast('Cancela levantada • passagem liberada.','good',1800);beep(1040,80,'sine');return true;}
  function ottoviasTollLocal(toll,x,z){const dx=x-toll.x,dz=z-toll.z,c=Math.cos(toll.heading),s=Math.sin(toll.heading);return{x:dx*c-dz*s,z:dx*s+dz*c};}
  function registerOttoviasTollPassage(toll,authorized=true){const data=ensureOttoviasState(),now=Date.now();toll.tracking=false;toll.entrySide=0;toll.lastLocalZ=0;if(authorized){data.passes++;toll.paymentPending=false;toll.openUntil=Math.min(Number(toll.openUntil||now+900),now+900);saveState(true);toast(`Passagem concluída • ${toll.name}.`,'good',1400);return true;}if(now-Number(toll.lastEvasionAt||0)<8000)return false;toll.lastEvasionAt=now;data.violations++;data.lastViolationAt=now;saveState(true);michelleAddNews('toll','Evasão de pedágio registrada',`${toll.name}: a patrulha foi acionada para uma abordagem educativa.`,`toll-evasion:${toll.id}:${now}`,'attention',false);if(typeof startTollEvasionPursuit==='function')startTollEvasionPursuit(toll);else toast('Evasão registrada: reduza e aguarde a patrulha.','warn',2600);return false;}
  function updateOttoviasTollPassage(toll,now){if(!player.vehicle){toll.tracking=false;toll.entrySide=0;return;}const local=ottoviasTollLocal(toll,player.x,player.z),insideApproach=Math.abs(local.x)<13.5&&Math.abs(local.z)<14.5;if(insideApproach&&!toll.tracking){toll.tracking=true;toll.entrySide=local.z>=0?1:-1;toll.lastLocalZ=local.z;}if(toll.tracking){const crossed=toll.entrySide>0?local.z<-6.2:local.z>6.2;if(crossed&&Math.abs(local.x)<13.5){const authorized=toll.paymentPending||now<Number(toll.openUntil||0);registerOttoviasTollPassage(toll,authorized);return;}if(Math.abs(local.z)>16||Math.abs(local.x)>15.5){toll.tracking=false;toll.entrySide=0;}else toll.lastLocalZ=local.z;}const open=now<Number(toll.openUntil||0),gateDistance=Math.abs(local.z-4.1);if(Math.abs(local.x)<7.0&&Math.abs(local.z)<10&&!open){if(gateDistance<5.2)player.car.speed=Math.sign(player.car.speed||1)*Math.min(Math.abs(player.car.speed||0),1.65);if(gateDistance<1.45)player.car.speed=0;if(now-Number(toll.lastWarnAt||0)>5000){toll.lastWarnAt=now;const next=toll.paymentPending?'LEVANTAR':'PAGAR';toast(`Pedágio ${toll.name}: use ${next} no botão extra do veículo.`,'warn',2200);updateContext?.(true);}}}
  function ottoviasTourTarget(){const data=ensureOttoviasState(),tour=data.tour;return tour.active?OTTOVIAS_TOUR_STOPS[Math.min(tour.index,OTTOVIAS_TOUR_STOPS.length-1)]:null;}
  function ottoviasSetTourWaypoint(){const target=ottoviasTourTarget();if(!target)return;const p=worldLayoutPoint(target.point);state.waypoint={id:target.id,name:`OTTOVIAS • ${target.name}`,x:p.x,z:p.z,navX:p.x,navZ:p.z,arrived:false};world.routePath=buildRoutePoints(player,state.waypoint);updateWaypointMarker();updateNavigation(0,true);saveState(true);}
  function startOttoviasTour(){const data=ensureOttoviasState();data.communication.active=false;data.communication.mode='';data.communication.index=0;data.tour.active=true;data.tour.index=0;data.tour.startedAt=Date.now();ottoviasSetTourWaypoint();closeModal();toast('Michelle: ronda iniciada. Passe pelos quatro biomas e retorne à central.','good',3200);}
  function cancelOttoviasTour(){const data=ensureOttoviasState();data.tour.active=false;data.tour.index=0;saveState(true);toast('Ronda OTTOVIAS encerrada.','warn',1500);}
  function completeOttoviasTour(){const data=ensureOttoviasState(),elapsed=Math.max(1,Date.now()-Number(data.tour.startedAt||Date.now()));data.tour.active=false;data.tour.index=0;data.tour.completed++;data.tour.bestMs=!data.tour.bestMs?elapsed:Math.min(data.tour.bestMs,elapsed);addCoins(80);addXP(120);state.waypoint=null;updateWaypointMarker();updateNavigation(0,true);saveState(true);toast(`Ronda OTTOVIAS concluída • ${Math.round(elapsed/1000)} s • +80 moedas • +120 XP`,'good',3500);}
  function ottoviasPlayerKey(){return String(playerDisplayName?.()||state.profile?.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();}
  function isOttoOttoviasPlayer(){const name=ottoviasPlayerKey();return name.includes('otto')||name.includes('ottinho')||name.includes('otinho');}
  function ottoviasCommunicationStops(mode){return mode==='otto'?OTTOVIAS_OTTO_STOPS:OTTOVIAS_COMM_STOPS;}
  function ottoviasCommunicationTarget(){const comm=ensureOttoviasState().communication,stops=ottoviasCommunicationStops(comm.mode);return comm.active?stops[Math.min(comm.index,stops.length-1)]:null;}
  function ottoviasSetCommunicationWaypoint(){const target=ottoviasCommunicationTarget();if(!target)return;const p=worldLayoutPoint(target.point);state.waypoint={id:target.id,name:`${target.icon} ${target.name}`,x:p.x,z:p.z,navX:p.x,navZ:p.z,arrived:false};world.routePath=buildRoutePoints(player,state.waypoint);updateWaypointMarker();updateNavigation(0,true);saveState(true);}
  function startOttoviasCommunicationMission(mode='press'){const data=ensureOttoviasState(),comm=data.communication;data.tour.active=false;comm.active=true;comm.mode=mode==='otto'&&isOttoOttoviasPlayer()?'otto':'press';comm.index=0;comm.startedAt=Date.now();ottoviasSetCommunicationWaypoint();closeModal();toast(comm.mode==='otto'?'Michelle: Operação Repórter Mirim iniciada! Faça a cobertura completa da OTTOVIAS.':'Michelle: plantão iniciado. Confira cidade, pedágio, neve e retorne com o boletim.','good',3600);}
  function cancelOttoviasCommunicationMission(){const comm=ensureOttoviasState().communication;comm.active=false;comm.mode='';comm.index=0;saveState(true);toast('Plantão de comunicação encerrado.','warn',1500);}
  function completeOttoviasCommunicationMission(){const data=ensureOttoviasState(),comm=data.communication,special=comm.mode==='otto',elapsed=Math.max(1,Date.now()-Number(comm.startedAt||Date.now()));comm.active=false;comm.index=0;comm.completed++;if(special){comm.specialComplete=true;state.flags.ottoviasReporterMirim=true;addCoins(120);addXP(180);}else{addCoins(70);addXP(110);}state.waypoint=null;updateWaypointMarker();updateNavigation(0,true);saveState(true);toast(special?`Operação Repórter Mirim concluída • +120 moedas • +180 XP`:`Boletim OTTOVIAS concluído • ${Math.round(elapsed/1000)} s • +70 moedas • +110 XP`,'good',3600);}
  function michelleClock(timestamp=Date.now()){try{return new Date(timestamp).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}catch{return '--:--';}}
  function michelleBiomeLabel(biome){return({city:'Travessia Urbana',desert:'Trecho Deserto',field:'Trecho Campo',snow:'Trecho Neve',beach:'Trecho Praia',country:'Trecho Rural'})[biome]||'rede viária do OTTHI World';}
  function michelleLocationLabel(x,z){const info=ottoviasNearestInfo(Number(x||0),Number(z||0));return info&&info.distance<24?michelleBiomeLabel(info.biome):'rede viária urbana';}
  function michelleTrafficTelemetry(){let actors=[];try{actors=typeof trafficActorList==='function'?trafficActorList():[];}catch{actors=[];}const now=performance.now(),moving=actors.filter(item=>Number(item.ref?.currentSpeed??item.speed??0)>.65&&!item.ref?.incidentLocked).length,held=actors.filter(item=>item.ref?.incidentLocked||now<Number(item.ref?.trafficHoldUntil||0)).length,responding=[...(world.policeCars||[]),...(world.ambulances||[]),...(world.fireTrucks||[])].filter(item=>item.incidentTargetId||item.targetFireId).length,activeIncident=world.activeIncident&&!world.activeIncident.resolved?world.activeIncident:null,activeFires=(world.fires||[]).filter(item=>item.active),openTolls=[...OTTOVIAS_RUNTIME.tolls.values()].filter(item=>Date.now()<Number(item.openUntil||0)).length,totalTolls=OTTOVIAS_RUNTIME.tolls.size,nearest=ottoviasNearestInfo(player.x,player.z),status=activeIncident||activeFires.length?'alerta':held>=4?'atencao':'livre';return{actors,moving,held,responding,activeIncident,activeFires,openTolls,totalTolls,nearest,status};}
  function michelleCurrentReport(){const live=michelleTrafficTelemetry(),data=ensureOttoviasState(),incident=live.activeIncident,fire=live.activeFires[0],location=incident?michelleLocationLabel(incident.x,incident.z):fire?(fire.name||michelleLocationLabel(fire.x,fire.z)):(live.nearest&&live.nearest.distance<12?michelleBiomeLabel(live.nearest.biome):'rede OTTOVIAS');let level='normal',headline='Operação normal na rede OTTOVIAS',summary='Não há acidente nem incêndio ativo neste momento.';if(incident){level='alert';headline=incident.fire?'Acidente com princípio de incêndio':'Acidente em atendimento';summary=`Ocorrência real do jogo em ${location}. ${live.responding} equipe${live.responding===1?' está':'s estão'} em deslocamento ou atendimento.`;}else if(fire){level='alert';headline='Chamado de incêndio em atendimento';summary=`Os bombeiros foram acionados para ${location}. A ocorrência permanece ativa no jogo.`;}else if(live.held>=4){level='attention';headline='Fluxo com retenção momentânea';summary=`Há ${live.held} veículos aguardando liberação no trânsito simulado. Dirija com atenção.`;}const currentBiome=live.nearest&&live.nearest.distance<12?michelleBiomeLabel(live.nearest.biome):'fora da faixa principal';return{...live,level,headline,summary,location,currentBiome,passes:Number(data.passes||0),spent:Number(data.spent||0),resolved:Number(state.cityServices?.accidentsResolved||0),firesResolved:Number(state.cityServices?.firesExtinguished||0)};}
  function michelleShouldBroadcast(level,type){const data=ensureOttoviasState(),mode=data.newsMode,now=Date.now(),critical=level==='alert'&&['accident','fire'].includes(type),cooldown=mode==='all'?20000:45000;if(mode==='silent'||(mode==='critical'&&!critical)||now-OTTOVIAS_RUNTIME.lastBroadcastAt<cooldown)return false;OTTOVIAS_RUNTIME.lastBroadcastAt=now;return true;}
  function setMichelleNewsMode(mode){const data=ensureOttoviasState();data.newsMode=['critical','all','silent'].includes(mode)?mode:'critical';saveState(true);toast(data.newsMode==='silent'?'Noticiário silencioso. Consulte as notícias quando quiser.':data.newsMode==='all'?'Avisos completos ativados.':'Somente alertas importantes ativados.','good',1800);return data.newsMode;}
  function michelleAddNews(type,title,body,key='',level='info',announce=false){const data=ensureOttoviasState(),dedupe=String(key||`${type}:${title}:${body}`);if(data.news.some(item=>item.key===dedupe))return false;const item={id:`michelle-${++data.newsSeq}`,key:dedupe,type,title,body,level,at:Date.now()};data.news.unshift(item);data.news=data.news.slice(0,OTTOVIAS_NEWS_LIMIT);data.lastBulletinAt=item.at;saveState();if(announce&&michelleShouldBroadcast(level,type))toast(`📡 Michelle informa: ${title}`,(level==='alert'||level==='attention')?'warn':'good',2600);return item;}
  function michelleObserveWorld(force=false){const now=performance.now();if(!force&&now-OTTOVIAS_RUNTIME.newsCheckAt<1600)return;OTTOVIAS_RUNTIME.newsCheckAt=now;const live=michelleTrafficTelemetry(),incidentId=String(live.activeIncident?.id||'');if(incidentId!==OTTOVIAS_RUNTIME.observedIncidentId){if(incidentId){const incident=live.activeIncident,place=michelleLocationLabel(incident.x,incident.z);michelleAddNews('accident',incident.fire?'Acidente com princípio de incêndio':'Acidente registrado',`Equipes acionadas para ${place}. A ocorrência continua ativa no mundo do jogo.`,`incident-open:${incidentId}`,'alert',true);}else if(OTTOVIAS_RUNTIME.observedIncidentId){michelleAddNews('clear','Via liberada após atendimento','As equipes concluíram o atendimento e o fluxo foi liberado no mundo do jogo.',`incident-clear:${OTTOVIAS_RUNTIME.observedIncidentId}`,'good',false);}OTTOVIAS_RUNTIME.observedIncidentId=incidentId;}
    const fireIds=new Set(live.activeFires.map(item=>String(item.id)));for(const fire of live.activeFires)if(!OTTOVIAS_RUNTIME.observedFireIds.has(String(fire.id)))michelleAddNews('fire','Bombeiros acionados',`${fire.name||'Ocorrência de incêndio'} está em atendimento.`,`fire-open:${fire.id}:${Number(fire.startedAt||0)}`,'alert',true);for(const oldId of OTTOVIAS_RUNTIME.observedFireIds)if(!fireIds.has(oldId))michelleAddNews('clear','Incêndio controlado','A ocorrência acompanhada pela Central OTTOVIAS foi encerrada pelas equipes.',`fire-clear:${oldId}:${Number(state.cityServices?.firesExtinguished||0)}`,'good',false);OTTOVIAS_RUNTIME.observedFireIds=fireIds;
    const data=ensureOttoviasState(),tollAt=Number(data.lastTollAt||0);if(tollAt>OTTOVIAS_RUNTIME.observedTollAt){const toll=ottoviasTollRecord(data.lastTollId);michelleAddNews('toll','Passagem registrada no pedágio',`${toll?.name||'Praça OTTOVIAS'} liberou uma passagem por ${Number(toll?.cost||5)} moedas.`,`toll:${tollAt}`,'info',false);OTTOVIAS_RUNTIME.observedTollAt=tollAt;}
    const trafficStatus=live.held>=4?'attention':'normal',wallNow=Date.now();if(trafficStatus==='attention'){if(OTTOVIAS_RUNTIME.observedTrafficStatus!=='attention')OTTOVIAS_RUNTIME.trafficAttentionSince=wallNow;const sustained=wallNow-OTTOVIAS_RUNTIME.trafficAttentionSince>12000;if(sustained&&wallNow-OTTOVIAS_RUNTIME.lastTrafficBulletinAt>120000){OTTOVIAS_RUNTIME.lastTrafficBulletinAt=wallNow;michelleAddNews('traffic','Retenção prolongada',`${live.held} veículos aguardam liberação. Consulte o Noticiário para acompanhar.`,`traffic-attention:${Math.floor(wallNow/120000)}`,'attention',true);}}else if(OTTOVIAS_RUNTIME.observedTrafficStatus==='attention'&&wallNow-OTTOVIAS_RUNTIME.trafficAttentionSince>12000){michelleAddNews('traffic','Fluxo normalizado','A retenção terminou e os veículos voltaram a circular.',`traffic-clear:${Math.floor(wallNow/120000)}`,'good',false);OTTOVIAS_RUNTIME.trafficAttentionSince=0;}OTTOVIAS_RUNTIME.observedTrafficStatus=trafficStatus;}
  function michelleNewsMarkup(){const data=ensureOttoviasState();if(!data.news.length)return '<p class="michelle-empty">Ainda não há ocorrências registradas nesta sessão.</p>';return `<div class="michelle-news-list">${data.news.slice(0,8).map(item=>`<article class="michelle-news michelle-news-${item.level||'info'}"><span>${item.type==='accident'?'🚨':item.type==='fire'?'🔥':item.type==='toll'?'🎫':item.type==='traffic'?'🚙':'✅'}</span><div><b>${item.title}</b><p>${item.body}</p><small>${michelleClock(item.at)}</small></div></article>`).join('')}</div>`;}
  function michelleAnswer(question=''){const q=String(question||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),r=michelleCurrentReport(),comm=ensureOttoviasState().communication;comm.questionsAnswered++;saveState();if(/acidente|ocorrencia|resgate|ambulancia/.test(q))return r.activeIncident?`${r.headline}. ${r.summary}`:`Não há acidente ativo agora. O histórico registra ${r.resolved} atendimento${r.resolved===1?'':'s'} concluído${r.resolved===1?'':'s'}.`;if(/incendio|fogo|bombeiro/.test(q))return r.activeFires.length?`${r.activeFires.length} ocorrência${r.activeFires.length===1?' está':'s estão'} ativa${r.activeFires.length===1?'':'s'}: ${r.activeFires.map(item=>item.name).join(', ')}.`:`Não há incêndio ativo agora. ${r.firesResolved} ocorrência${r.firesResolved===1?' foi':'s foram'} controlada${r.firesResolved===1?'':'s'} até aqui.`;if(/pedagio|cancela|moeda|tarifa/.test(q))return `A OTTOVIAS possui ${r.totalTolls} praças. ${r.openTolls} estão com liberação ativa neste instante. Você já fez ${r.passes} ${r.passes===1?'passagem':'passagens'} e gastou ${r.spent} moedas.`;if(/transito|trafego|movimento|rodovia|via/.test(q))return `${r.headline}. ${r.moving} veículos estão em movimento e ${r.held} aguardam por retenção ou segurança. Você está em ${r.currentBiome}.`;if(/missao|trabalho|plantao|ronda/.test(q))return comm.active?`Seu plantão está ativo. Próxima pauta: ${ottoviasCommunicationTarget()?.instruction||'retorne à Central de Comunicação'}`:`Você pode iniciar o Plantão de Comunicação ou a Volta OTTOVIAS. Eu organizo cada destino no GPS.`;if(/otto|ottinho|otinho|reporter/.test(q))return isOttoOttoviasPlayer()?'A Operação Repórter Mirim está disponível para você. Vamos visitar os trechos, observar o trânsito e produzir uma reportagem completa.':'A Operação Repórter Mirim aparece quando o personagem se chama Otto, Ottinho ou Otinho.';if(/noticia|boletim|agora|situacao|acontecendo/.test(q))return `${r.headline}. ${r.summary} Pedágios com liberação ativa: ${r.openTolls} de ${r.totalTolls}.`;if(/onde|local|mapa|gps/.test(q))return `Você está em ${r.currentBiome}. Posso abrir o mapa ou marcar os destinos das missões diretamente no GPS.`;return `Eu acompanho os dados reais desta partida: acidentes, incêndios, fluxo dos veículos, equipes de emergência, pedágios e missões. Agora: ${r.headline.toLowerCase()}.`;}
  function michelleSpeak(text){const phrase=String(text||'').trim();if(!phrase)return false;OTTOVIAS_RUNTIME.lastSpokenText=phrase;if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined'){toast('A resposta está escrita na tela. Voz não disponível neste aparelho.','warn',1800);return false;}try{window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(phrase);utterance.lang='pt-BR';utterance.rate=.96;utterance.pitch=1.03;const voice=window.speechSynthesis.getVoices?.().find(item=>String(item.lang||'').toLowerCase().startsWith('pt-br'));if(voice)utterance.voice=voice;window.speechSynthesis.speak(utterance);return true;}catch{return false;}}
