  function trafficIncidentWorkshopProtected(x,z){const wp=worldLayoutPoint('workshop',{x:22,z:-18});return Math.hypot(Number(x)-wp.x,Number(z)-wp.z)<18.5;}
  function clearWorkshopTrafficChoke(a,b){if(!a||!b)return false;separateIncidentActors(a,b);const now=performance.now();for(const actor of[a,b]){const ref=actor?.ref;if(!ref)continue;ref.incidentLocked=false;ref.incidentUntil=now+1200;ref.trafficHoldUntil=now+900;if(Number.isFinite(Number(ref.currentSpeed)))ref.currentSpeed=Math.max(0,Math.min(Number(actor.speed||ref.currentSpeed||0),2.2));}world.nextTrafficIncidentAt=Math.max(Number(world.nextTrafficIncidentAt||0),now+5500);return true;}
  function serviceKindForJob(jobOrId){const id=typeof jobOrId==='string'?jobOrId:jobOrId?.id;return SERVICE_JOB_KIND[id]||'';}
  function serviceVehiclePools(kind=''){if(kind==='police')return world.policeCars||[];if(kind==='firefighter')return world.fireTrucks||[];if(kind==='paramedic')return world.ambulances||[];return[...(world.policeCars||[]),...(world.fireTrucks||[]),...(world.ambulances||[])];}
