  function createLearningPlaza(){const math=worldLayoutPoint('learningMath'),pt=worldLayoutPoint('learningPortuguese'),en=worldLayoutPoint('learningEnglish'),entry=worldLayoutPoint('learningEntrance');createOttonSchoolShell();createLearningStation('math','math',math.x,math.z,0x27b36a,'＋','Treinar Matemática Otton');createLearningStation('portuguese','portuguese',pt.x,pt.z,0x7b5ce6,'A','Treinar Português Otton');createLearningStation('english','english',en.x,en.z,0x168de2,'E','Treinar English Otton');const thamis=createNPC('tia-thamis','Tia Thamis',entry.x+5.85,entry.z+3.0,0xff6900,1.05);applyTiaThamisReferenceSkin(thamis);thamis.stationary=true;thamis.stationaryHeading=-Math.PI/2;thamis.group.rotation.y=-Math.PI/2;thamis.group.position.y=0;const action=world.interactables.find(it=>it.id==='npc-tia-thamis');if(action){action.type='education';action.icon='👩‍🏫';action.label='Tia Thamis • Otton Connect';action.radius=7.2;action.priority=360;action.getPos=()=>({x:thamis.group.position.x,z:thamis.group.position.z});action.action=()=>window.OTTHI_TIA_THAMIS?.open?.('welcome');}}

