  function openWorkshopScrapyard(){workshopEnsureScrapyardVisual();const scrap=workshopScrapyardState(),rows=WORKSHOP_PART_DEFS.map(def=>({def,qty:Number(scrap.parts[def.id]||0)})).filter(x=>x.qty>0),stock=rows.reduce((n,x)=>n+x.qty,0),html=rows.length?rows.map(({def,qty})=>`<div class="choice"><b>${def.icon} ${escapeHtml(def.name)}</b><span>${qty} peça(s) • ${workshopScrapPartPrice(def.id)} moedas cada</span><div class="modal-actions"><button class="btn compact" data-scrap-one="${def.id}">Vender 1</button><button class="btn good compact" data-scrap-all="${def.id}">Vender todas</button></div></div>`).join(''):'<div class="choice"><b>Estoque vazio</b><span>Desmonte veículos classificados como SEM CONSERTO para recuperar componentes.</span></div>';openModal('♻️ Ferro-Velho OTTHI',`<div class="dialogue-box"><b>Sucata e peças reaproveitáveis</b><p>Veículos sem conserto podem ser vendidos inteiros ou desmontados. O estoque de peças é persistente.</p><small>${scrap.soldVehicles||0} sucata(s) vendida(s) • ${scrap.dismantledVehicles||0} desmontado(s) • ${stock} peça(s) • receita ${scrap.revenue||0}</small></div><div class="choice-grid">${html}</div><div class="modal-actions"><button class="btn" data-scrap-yard>Voltar ao pátio</button></div>`,root=>{$$('[data-scrap-one]',root).forEach(btn=>btn.onclick=()=>{if(workshopSellScrapPart(btn.dataset.scrapOne,false))openWorkshopScrapyard();});$$('[data-scrap-all]',root).forEach(btn=>btn.onclick=()=>{if(workshopSellScrapPart(btn.dataset.scrapAll,true))openWorkshopScrapyard();});$('[data-scrap-yard]',root).onclick=openWorkshopYard;});}
  function openWorkshopYard(){const separated=workshopReorganizeLegacyYardVehicles(),items=(world.vehicles||[]).filter(v=>v?.group&&v.workshopYardStatus).map(v=>({vehicle:v,status:workshopVehicleServiceStatus(v),owner:workshopVehicleOwnerMeta(v),durability:typeof vehicleDurabilityV704==='function'?vehicleDurabilityV704(v):100})),order=['ready','pending','unrepairable'],sections=order.map(status=>{const meta=workshopYardStatusMeta(status),list=items.filter(x=>x.status===status);return`<section class="avatar-section"><h3>${meta.icon} ${meta.label} • ${list.length}</h3><div class="choice-grid">${list.length?list.map(x=>`<button class="choice" data-yard-vehicle="${escapeHtml(String(x.vehicle.id))}"><b>🚗 ${escapeHtml(x.vehicle.label||x.vehicle.id)}</b><span>${escapeHtml(x.owner.name)} • integridade ${Math.round(x.durability)}%</span><small>Vaga ${escapeHtml(String(x.vehicle.workshopYardSlot||''))} • toque para abrir o atendimento</small></button>`).join(''):'<div class="choice"><span>Nenhum veículo nesta área.</span></div>'}</div></section>`;}).join('');openModal('Pátio da Oficina',`<div class="dialogue-box"><b>${separated?`${separated} veículo(s) separado(s) automaticamente`:'Veículos separados em vagas individuais'}</b><p>Nenhum carro compartilha a mesma vaga. Toque no veículo para reparar, retirar ou levar à garagem quando estiver liberado.</p></div>${sections}<div class="modal-actions"><button class="btn good" data-yard-scrapyard>♻️ Ferro-Velho / peças</button><button class="btn" data-yard-back>Voltar às OS abertas</button></div>`,root=>{$$('[data-yard-vehicle]',root).forEach(btn=>btn.onclick=()=>openWorkshopVehicleDiagnostic(btn.dataset.yardVehicle));$('[data-yard-scrapyard]',root).onclick=openWorkshopScrapyard;$('[data-yard-back]',root).onclick=openWorkshopServiceDesk;});}
  function workshopPartReport(vehicle){const record=workshopComponentRecord(vehicle);return WORKSHOP_PART_DEFS.map(def=>{const condition=clamp(Math.round(Number(record?.parts?.[def.id]??100)),0,100);return{...def,condition,status:condition<35?'CRÍTICO':condition<60?'DEFEITO':condition<82?'ATENÇÃO':condition<96?'DESGASTE':'OK',severity:condition<60?'bad':condition<96?'warn':'good'};});}
