  function workshopWheelLabels(count){if(count===2)return['Roda traseira','Roda dianteira'];if(count===6)return['Traseira esquerda','Traseira direita','Eixo central esquerdo','Eixo central direito','Dianteira esquerda','Dianteira direita'];return['Traseira esquerda','Traseira direita','Dianteira esquerda','Dianteira direita'].slice(0,count).map((x,i)=>x||`Roda ${i+1}`);}
