    if(input.mobilityAccelerate&&currentSpeed<-.04)return{throttle:0,brake:true,reverse:false};
    if(throttle<-.05&&currentSpeed>.04)return{throttle:0,brake:true,reverse:false};
    if(throttle>.05&&currentSpeed<-.04)return{throttle:0,brake:true,reverse:false};
