  const PLAYER_GARAGE_MAX_SLOTS=16,PLAYER_GARAGE_DISPLAY_FIRST_SLOT=4,PLAYER_GARAGE_DISPLAY_LAST_SLOT=PLAYER_GARAGE_DISPLAY_FIRST_SLOT+PLAYER_GARAGE_MAX_SLOTS-1;
