  function playerGarageDisplaySlotIds(){return Array.from({length:PLAYER_GARAGE_MAX_SLOTS},(_,i)=>String(PLAYER_GARAGE_DISPLAY_FIRST_SLOT+i));}
  function ensurePlayerGarageState(){ensureOtthiWorldState();state.vehicles.owned=[...new Set(['garage-orange',...(state.vehicles.owned||[])].map(String).filter(Boolean))];state.vehicles.primaryId=state.vehicles.owned.includes(state.vehicles.primaryId)?state.vehicles.primaryId:'garage-orange';const current=state.vehicles.garage||{};current.slots={'1':'garage-orange',...(current.slots||{})};current.stored={...(current.stored||{})};current.purchasedAt={'garage-orange':0,...(current.purchasedAt||{})};state.vehicles.garage=current;for(const slot of['1','2','3'])if(!state.vehicles.owned.includes(String(current.slots[slot]||'')))current.slots[slot]='';const allowed=playerGarageDisplaySlotIds(),old=current.displaySlots&&typeof current.displaySlots==='object'?current.displaySlots:{},displaySlots={},used=new Set();for(const slot of allowed){const id=String(old[slot]||'');if(id&&state.vehicles.owned.includes(id)&&!used.has(id)){displaySlots[slot]=id;used.add(id);}}const legacyIds=Object.entries(old).sort((a,b)=>Number(a[0])-Number(b[0])).map(([,id])=>String(id||'')).filter(id=>id&&state.vehicles.owned.includes(id));for(const id of[...legacyIds,...state.vehicles.owned]){if(used.has(id))continue;const free=allowed.find(slot=>!displaySlots[slot]);if(!free)break;displaySlots[free]=id;used.add(id);}current.displaySlots=displaySlots;return current;}
