  function playerGarageDisplaySlot(number=PLAYER_GARAGE_DISPLAY_FIRST_SLOT){const center=worldLayoutPoint('homeGarage',{x:-31,z:46}),raw=Math.round(Number(number)||PLAYER_GARAGE_DISPLAY_FIRST_SLOT);if(raw<=3)return playerGarageSlot(raw);const index=clamp(raw,PLAYER_GARAGE_DISPLAY_FIRST_SLOT,PLAYER_GARAGE_DISPLAY_LAST_SLOT),n=index-PLAYER_GARAGE_DISPLAY_FIRST_SLOT,col=n%4,row=Math.floor(n/4);return{x:center.x-7.3-col*3.15,z:center.z-4.8+row*3.2,heading:0,slot:String(index)};}
